package statusbar

import (
	"fmt"
	"github.com/charmbracelet/lipgloss"
	"drover-code/internal/tui/styles"
)

type StatusBar struct {
	ModelName    string
	InputTokens  int
	OutputTokens int
	AgentBusy    bool
	Width        int
}

func New(modelName string) *StatusBar {
	return &StatusBar{ModelName: modelName}
}

func (s *StatusBar) SetSize(width, _ int) {
	s.Width = width
}

func (s *StatusBar) Update(msg tea.Msg) (*StatusBar, tea.Cmd) {
	// Future: react to token/busy messages
	return s, nil
}

func (s *StatusBar) View() string {
	if s.Width == 0 {
		return ""
	}
	left := styles.Accent.Render("◉ " + s.ModelName)
	busy := ""
	if s.AgentBusy {
		busy = styles.Busy.Render(" ● LIVE")
	}
	right := fmt.Sprintf("%s  in:%d  out:%d", busy, s.InputTokens, s.OutputTokens)
	used := lipgloss.Width(left) + lipgloss.Width(right)
	fill := s.Width - used
	if fill < 0 { fill = 0 }
	filler := styles.StatusBar.Width(fill).Render(" ")
	return lipgloss.JoinHorizontal(lipgloss.Top, left, filler, right)
}

package liveregion

import (
	"fmt"
	"strings"
	"github.com/charmbracelet/lipgloss"
	"drover-code/internal/tui/components/toolspinner"
	"drover-code/internal/tui/styles"
)

type LiveRegion struct {
	Streaming   bool
	StreamLines string
	ActiveTools map[int]*toolspinner.ToolSpinner
	ToolOrder   []int
	Width       int
}

func New() *LiveRegion {
	return &LiveRegion{
		ActiveTools: make(map[int]*toolspinner.ToolSpinner),
	}
}

func (l *LiveRegion) SetSize(width, _ int) { l.Width = width }

func (l *LiveRegion) View() string {
	if !l.Streaming && len(l.ActiveTools) == 0 {
		return ""
	}
	var b strings.Builder
	for _, idx := range l.ToolOrder {
		if ts, ok := l.ActiveTools[idx]; ok {
			row := fmt.Sprintf("%s  %s  %s", ts.Spinner.View(),
				styles.ToolName.Render(ts.Name),
				styles.ToolSummary.Render(ts.Summary))
			b.WriteString(styles.ToolRow.Render(row) + "\n")
		}
	}
	if l.Streaming && l.StreamLines != "" {
		preview := lastLines(l.StreamLines, styles.LiveRegionMaxLines)
		preview = softenAssistantParagraphBreaks(preview)
		innerW := max(l.Width-10, 24)
		b.WriteString(lipgloss.NewStyle().Width(innerW).Render(preview))
	}
	content := strings.TrimRight(b.String(), "\n")
	if content == "" { return "" }
	return styles.LiveRegion.Width(l.Width-4).Render(content)
}

