package toolspinner

import (
	"github.com/charmbracelet/bubbles/spinner"
	"drover-code/internal/tui/styles"
)

type ToolSpinner struct {
	Spinner spinner.Model
	Name    string
	Summary string
}

func NewToolSpinner(name, summary string) *ToolSpinner {
	s := spinner.New()
	s.Spinner = spinner.Dot
	s.Style = styles.ToolPending
	return &ToolSpinner{Spinner: s, Name: name, Summary: summary}
}

func (t *ToolSpinner) View() string {
	return t.Spinner.View() + " " + t.Name + " " + t.Summary
}

